package org.shiraz.fixture;
import android.content.res.*;
import android.graphics.*;
import android.graphics.drawable.*;
public final class GradientFixture {
 private static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 private static int pixel(GradientDrawable drawable,int w,int h,int x,int y){Bitmap image=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);try{drawable.setBounds(0,0,w,h);drawable.draw(new Canvas(image));return image.getPixel(x,y);}finally{image.recycle();}}
 public static void check(){
  GradientDrawable shape=new GradientDrawable();shape.setColor(Color.RED);shape.setCornerRadius(4);shape.setStroke(2,Color.BLUE);check(pixel(shape,20,20,0,0)==0&&pixel(shape,20,20,10,10)==Color.RED&&pixel(shape,20,20,10,1)==Color.BLUE,"Rounded fill and inset stroke");shape.setAlpha(128);check(pixel(shape,20,20,10,10)==0x80ff0000&&pixel(shape,20,20,10,1)==0x800000ff,"Group alpha including fill/stroke overlap");shape.setAlpha(255);shape.setColor(new ColorStateList(new int[][]{{android.R.attr.state_pressed},{}},new int[]{Color.GREEN,Color.RED}));shape.setState(new int[]{android.R.attr.state_pressed});check(pixel(shape,20,20,10,10)==Color.GREEN,"Stateful fill");shape.setTintList(ColorStateList.valueOf(Color.BLUE));check(pixel(shape,20,20,10,10)==Color.BLUE,"Shape tint");shape.setTintList(null);shape.setCornerRadii(new float[]{8,8,0,0,0,0,0,0});check(pixel(shape,20,20,1,1)==0&&pixel(shape,20,20,18,1)!=0,"Independent corners");
  GradientDrawable pill=new GradientDrawable();pill.setColor(Color.RED);pill.setCornerRadius(100);check(pixel(pill,40,10,10,0)==Color.RED,"Large radius preserves circular pill ends");
  int[] colors={Color.RED,Color.BLUE};GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,colors);colors[0]=Color.GREEN;int left=pixel(gradient,20,10,1,5),right=pixel(gradient,20,10,18,5);check(Color.red(left)>220&&Color.blue(left)<30&&Color.blue(right)>220,"Linear gradient and defensive colors");Bitmap scaled=Bitmap.createBitmap(60,40,Bitmap.Config.ARGB_8888);try{Canvas canvas=new Canvas(scaled);canvas.translate(3,4);canvas.scale(2,2);gradient.setBounds(2,3,22,13);gradient.draw(canvas);check(scaled.getPixel(6,15)==0&&Color.red(scaled.getPixel(8,15))>220&&Color.blue(scaled.getPixel(44,15))>220,"Gradient cache supports transformed placement");}finally{scaled.recycle();}gradient.setOrientation(GradientDrawable.Orientation.RIGHT_LEFT);check(Color.blue(pixel(gradient,20,10,1,5))>220,"Orientation invalidates cached gradient");gradient.setOrientation(GradientDrawable.Orientation.LEFT_RIGHT);int small=pixel(gradient,10,10,1,5),large=pixel(gradient,40,10,1,5);check(Color.red(large)>Color.red(small),"Gradient cache follows resized bounds");gradient.setUseLevel(true);gradient.setLevel(5000);check(Color.blue(pixel(gradient,20,10,15,5))==255,"Gradient level scales endpoints");gradient.setUseLevel(false);gradient.setGradientType(GradientDrawable.RADIAL_GRADIENT);gradient.setGradientRadius(10);check(Color.red(pixel(gradient,20,20,10,10))>220&&Color.blue(pixel(gradient,20,20,0,0))==255,"Radial distance");gradient.setGradientType(GradientDrawable.SWEEP_GRADIENT);check(Color.red(pixel(gradient,20,20,18,10))>220&&Color.blue(pixel(gradient,20,20,10,1))>170,"Sweep orientation");gradient.setGradientType(GradientDrawable.LINEAR_GRADIENT);gradient.setShape(GradientDrawable.OVAL);check(pixel(gradient,20,20,0,0)==0&&pixel(gradient,20,20,10,10)!=0,"Gradient respects oval mask");gradient.setColorFilter(new PorterDuffColorFilter(Color.GREEN,PorterDuff.Mode.SRC));check(pixel(gradient,20,20,0,0)==0&&pixel(gradient,20,20,10,10)==Color.GREEN,"Alpha-creating filter stays inside gradient shape");gradient.setColorFilter(null);Outline outline=new Outline();gradient.getOutline(outline);check(outline.getAlpha()==1,"Opaque gradient oval supplies shadow outline");gradient.setShape(GradientDrawable.RECTANGLE);gradient.setColor(Color.GREEN);check(pixel(gradient,20,20,10,10)==Color.GREEN,"Solid color removes gradient");
  GradientDrawable line=new GradientDrawable();line.setShape(GradientDrawable.LINE);line.setStroke(2,Color.RED,3,3);check(pixel(line,20,10,1,5)!=0&&pixel(line,20,10,4,5)==0,"Dashed line shape");try{shape.setCornerRadii(new float[2]);throw new AssertionError("Bad corner array accepted");}catch(IllegalArgumentException expected){}
  ring();
  System.out.println("GRADIENT_SHAPE_PIXELS_OK");
 }
 public static void ring(){
  GradientDrawable ring=new GradientDrawable();ring.setShape(GradientDrawable.RING);ring.setColor(Color.RED);
  check(pixel(ring,90,90,80,45)==0,"Ring defaults to level zero");ring.setLevel(10000);
  check(pixel(ring,90,90,80,45)==Color.RED&&pixel(ring,90,90,45,45)==0&&pixel(ring,90,90,89,45)==0,"Default ring ratios and hole");
  check(pixel(ring,180,100,160,50)==Color.RED&&pixel(ring,180,100,120,50)==0,"Ratios recompute from width on resize");
  ring.setInnerRadius(10);ring.setThickness(10);check(pixel(ring,60,40,45,20)==Color.RED&&pixel(ring,60,40,30,20)==0,"Explicit radii and non-square bounds");
  ring.setLevel(2500);check(pixel(ring,60,40,40,30)==Color.RED&&pixel(ring,60,40,20,30)==0&&pixel(ring,60,40,40,10)==0,"Clockwise quarter ring");
  ring.setLevel(5000);check(pixel(ring,60,40,20,30)==Color.RED&&pixel(ring,60,40,20,10)==0,"Half ring level update");
  ring.setColors(new int[]{Color.RED,Color.BLUE});ring.setLevel(10000);check(pixel(ring,60,40,40,10)!=0&&pixel(ring,60,40,30,20)==0,"Gradient ring mask");ring.setLevel(2500);check(pixel(ring,60,40,40,10)==0,"Ring level invalidates gradient cache");
  ring.setLevel(10000);ring.setColorFilter(new PorterDuffColorFilter(Color.GREEN,PorterDuff.Mode.SRC));check(pixel(ring,60,40,30,20)==0&&pixel(ring,60,40,45,20)==Color.GREEN,"Filter preserves ring hole");ring.setColorFilter(null);ring.setColor(Color.RED);ring.setStroke(2,Color.BLUE);check(Color.blue(pixel(ring,60,40,40,20))>0,"Inner edge stroke");
  Outline outline=new Outline();ring.getOutline(outline);check(outline.isEmpty(),"Nonconvex ring has no outline");
  try{ring.setThicknessRatio(0);throw new AssertionError("Zero ratio accepted");}catch(IllegalArgumentException expected){}
  try{ring.setInnerRadiusRatio(Float.NaN);throw new AssertionError("NaN ratio accepted");}catch(IllegalArgumentException expected){}
 }
 public static void xml(Resources resources){GradientDrawable ring=(GradientDrawable)resources.getDrawable(resources.getIdentifier("shape_ring","drawable","org.shiraz.fixture"));check(pixel(ring,60,40,45,20)==Color.RED&&pixel(ring,60,40,30,20)==0,"XML full ring independent of level");check(ring.getGradientType()==GradientDrawable.LINEAR_GRADIENT,"Root type attribute has no gradient effect");ring.setLevel(2500);check(pixel(ring,60,40,20,10)==Color.RED,"Shape useLevel is separate from gradient level");GradientDrawable ratioRing=(GradientDrawable)resources.getDrawable(resources.getIdentifier("shape_ring_ratio","drawable","org.shiraz.fixture"));check(pixel(ratioRing,80,80,65,40)==0,"XML ring default level");ratioRing.setLevel(10000);check(pixel(ratioRing,80,80,65,40)==Color.RED&&pixel(ratioRing,80,80,40,40)==0,"XML ring ratios");GradientDrawable shape=(GradientDrawable)resources.getDrawable(resources.getIdentifier("shape_solid","drawable","org.shiraz.fixture"));Rect pad=new Rect();check(shape.getIntrinsicWidth()==20&&shape.getIntrinsicHeight()==12&&shape.getPadding(pad)&&pad.equals(new Rect(1,2,3,4)),"XML size and padding");check(pixel(shape,20,20,10,10)==Color.RED&&pixel(shape,20,20,0,0)==0,"XML solid geometry");GradientDrawable linear=(GradientDrawable)resources.getDrawable(resources.getIdentifier("shape_linear","drawable","org.shiraz.fixture"));check(Color.red(pixel(linear,20,20,10,18))>220&&Color.blue(pixel(linear,20,20,10,1))>220,"XML gradient angle");GradientDrawable radial=(GradientDrawable)resources.getDrawable(resources.getIdentifier("shape_radial","drawable","org.shiraz.fixture"));check(Color.red(pixel(radial,20,20,10,10))>220&&Color.blue(pixel(radial,20,20,0,10))>220,"XML fractional radial radius");GradientDrawable intrinsic=(GradientDrawable)resources.getDrawable(resources.getIdentifier("shape_radial_intrinsic","drawable","org.shiraz.fixture"));check(Color.blue(pixel(intrinsic,20,20,5,10))>220&&intrinsic.getGradientRadius()==5,"Radial fraction uses intrinsic size");}
}
